CREATE OR REPLACE FUNCTION public.sgp_aplicar_export_diario(p_token text, p_linea text, p_nombre_archivo text, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE item jsonb; expected_year integer; expected_week integer; key text;
 seen text[]:=ARRAY[]::text[]; existing public.sgp_producciones%rowtype; response jsonb;
BEGIN
 IF jsonb_typeof(p_datos) IS DISTINCT FROM 'array' OR jsonb_array_length(p_datos)=0
 THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_DATA_INVALID'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_datos) LOOP
  key:=nullif(btrim(item->>'key_produccion'),'');
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR key IS NULL
   OR coalesce(item->>'anio','') !~ '^[0-9]{4}$'
   OR coalesce(item->>'semana_actual','') !~ '^[0-9]{1,2}$'
   OR nullif(btrim(item->>'id_linea'),'') IS DISTINCT FROM p_linea
  THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_EXPLICIT_PERIOD_REQUIRED'; END IF;
  expected_year:=(item->>'anio')::integer;expected_week:=(item->>'semana_actual')::integer;
  IF expected_year NOT BETWEEN 2020 AND 2100 OR expected_week NOT BETWEEN 1 AND 53
   OR key=ANY(seen) THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_PERIOD_AMBIGUOUS'; END IF;
  seen:=array_append(seen,key);
  -- Lock the existing production before delegating. This prevents a concurrent
  -- reprogramming from changing the year between validation and Export writes.
  SELECT * INTO existing FROM public.sgp_producciones WHERE key_produccion=key FOR UPDATE;
  IF FOUND AND (existing.id_linea IS DISTINCT FROM p_linea
    OR existing.anio IS DISTINCT FROM expected_year) THEN
   RAISE EXCEPTION 'PDT_EXPORT_YEAR_IMMUTABLE: %',key;
  END IF;
 END LOOP;
 -- Preserve installed Export authorization, reconciliation, history and response.
 response:=sgp_pdt_manual.original_aplicar_export_diario(p_token,p_linea,p_nombre_archivo,p_datos);
 -- The certified writer returns ok=true only after all writes complete. Fail closed
 -- on any future JSON rejection and roll back the delegated transaction as well.
 IF response->>'ok' IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION 'PDT_EXPORT_YEAR_DELEGATED_NOT_OK';
 END IF;
 -- Verify the original writer applied the week without changing the year.
 -- Missing rows remain the original writer's responsibility (e.g. FUERA_BASE).
 FOR item IN SELECT value FROM jsonb_array_elements(p_datos) LOOP
  key:=btrim(item->>'key_produccion');expected_year:=(item->>'anio')::integer;
  expected_week:=(item->>'semana_actual')::integer;
  SELECT * INTO existing FROM public.sgp_producciones WHERE key_produccion=key FOR UPDATE;
  IF FOUND THEN
   IF existing.id_linea IS DISTINCT FROM p_linea OR existing.anio IS DISTINCT FROM expected_year
    OR coalesce(existing.semana_actual,existing.semana_base) IS DISTINCT FROM expected_week
   THEN RAISE EXCEPTION 'PDT_EXPORT_YEAR_RESULT_MISMATCH: %',key; END IF;
  END IF;
 END LOOP;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_entrega_anular_v2(p_token text, p_linea uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE parent uuid; p public.sgp_aluminio_pendientes%rowtype; l public.sgp_pdt_entrega_lineas%rowtype; u text;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR']);
 IF nullif(btrim(p_motivo),'') IS NULL THEN RAISE EXCEPTION 'Motivo requerido'; END IF;
 SELECT d.id_pendiente INTO STRICT parent FROM public.sgp_pdt_entrega_lineas x JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE x.id_linea=p_linea;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent FOR UPDATE;
 SELECT * INTO STRICT l FROM public.sgp_pdt_entrega_lineas WHERE id_linea=p_linea FOR UPDATE;
 IF l.estado='ANULADA' THEN RETURN jsonb_build_object('ok',true,'duplicado',true); END IF;
 IF p.estado<>'PENDIENTE' THEN RAISE EXCEPTION 'Conciliar cierre antes de anular'; END IF;
 UPDATE public.sgp_pdt_entrega_lineas SET estado='ANULADA',motivo=p_motivo,anulado_por=u,anulado_en=now() WHERE id_linea=p_linea;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,tipo_evento,observacion,datos_nuevos)
 VALUES(parent,u,'ANULACION_ENTREGA_V2',p_motivo,jsonb_build_object('linea',p_linea));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_entrega_registrar_v2(p_token text, p_detalle uuid, p_entrega uuid, p_cantidad integer, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE grouped boolean;
BEGIN
 SELECT id_pieza='' INTO grouped FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle;
 IF grouped THEN
  IF sgp_pdt_multiorigen.es_registro_v4((SELECT id_pendiente FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle)) THEN
   RETURN sgp_pdt_multiorigen.grouped_nuevo_entrega(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
  END IF;
  RETURN sgp_pdt_multiorigen.grouped_original_entrega(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
 END IF;
 IF sgp_pdt_multiorigen.es_registro_v4((SELECT id_pendiente FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle)) THEN
  RETURN sgp_pdt_multiorigen.nuevo_sgp_pdt_entrega_registrar_v2(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
 END IF;
 RETURN sgp_pdt_multiorigen.original_sgp_pdt_entrega_registrar_v2(p_token,p_detalle,p_entrega,p_cantidad,p_clave);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_entrega_validar_v2(p_token text, p_linea uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.sgp_pdt_entrega_lineas%rowtype; parent uuid; u text; p public.sgp_aluminio_pendientes%rowtype;
BEGIN
 u:=public.sgp_validar_sesion_rol(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','SUPERVISOR DE PICKING']);
 SELECT d.id_pendiente INTO STRICT parent FROM public.sgp_pdt_entrega_lineas x JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE x.id_linea=p_linea;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent FOR UPDATE;
 SELECT * INTO STRICT l FROM public.sgp_pdt_entrega_lineas WHERE id_linea=p_linea FOR UPDATE;
 IF l.estado='VALIDADA' THEN RETURN jsonb_build_object('ok',true,'duplicado',true); END IF;
 IF p.estado<>'PENDIENTE' OR l.estado<>'REGISTRADA' THEN RAISE EXCEPTION 'Línea no apta'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=l.id_entrega AND estado='VALIDADA' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Entrega Picking sin validación inequívoca'; END IF;
 UPDATE public.sgp_pdt_entrega_lineas SET estado='VALIDADA',validado_por=u,validado_en=now() WHERE id_linea=p_linea;
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_entrega_anular_v1(p_token text, p_linea uuid, p_motivo text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE line sgp_pdt_manual.entregas%rowtype; parent uuid; actor text; parent_state text;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR']);
 IF nullif(btrim(p_motivo),'') IS NULL THEN RAISE EXCEPTION 'PDT_MANUAL_MOTIVO_REQUERIDO'; END IF;
 SELECT d.id_pendiente INTO STRICT parent FROM sgp_pdt_manual.entregas l
 JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE l.id_linea=p_linea;
 SELECT estado INTO parent_state FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent AND estado='PENDIENTE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_CERRADO'; END IF;
 SELECT * INTO STRICT line FROM sgp_pdt_manual.entregas WHERE id_linea=p_linea FOR UPDATE;
 IF line.estado='ANULADA' THEN RETURN jsonb_build_object('ok',true,'duplicado',true); END IF;
 UPDATE sgp_pdt_manual.entregas SET estado='ANULADA',anulado_por=actor,anulado_en=now(),motivo_anulacion=p_motivo
 WHERE id_linea=p_linea;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,observacion,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(parent,actor,p_motivo,parent_state,parent_state,'ANULACION_ENTREGA_MANUAL_PDT',jsonb_build_object('linea',p_linea,'cantidad',line.cantidad));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_entrega_registrar_v1(p_token text, p_detalle uuid, p_entrega uuid, p_cantidad integer, p_clave uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.sgp_aluminio_pendiente_detalles%rowtype; p public.sgp_aluminio_pendientes%rowtype;
 prior sgp_pdt_manual.entregas%rowtype; actor text; neto bigint; nuevo uuid;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING']);
 IF p_cantidad IS NULL OR p_cantidad<=0 OR p_clave IS NULL THEN RAISE EXCEPTION 'PDT_MANUAL_CANTIDAD_O_CLAVE_INVALIDA'; END IF;
 SELECT * INTO STRICT d FROM public.sgp_aluminio_pendiente_detalles WHERE id_detalle=p_detalle;
 SELECT * INTO STRICT p FROM public.sgp_aluminio_pendientes WHERE id_pendiente=d.id_pendiente FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM sgp_pdt_manual.detalles WHERE id_pendiente=p.id_pendiente)
 OR NOT EXISTS(SELECT 1 FROM sgp_pdt_manual.fuentes_validadas WHERE id_detalle=p_detalle)
 THEN RAISE EXCEPTION 'PDT_MANUAL_FUENTE_NO_VALIDADA'; END IF;
 SELECT * INTO prior FROM sgp_pdt_manual.entregas WHERE clave=p_clave;
 IF FOUND THEN
  IF prior.id_detalle<>p_detalle OR prior.id_entrega<>p_entrega OR prior.cantidad<>p_cantidad
  THEN RAISE EXCEPTION 'PDT_MANUAL_CLAVE_REUTILIZADA'; END IF;
  RETURN jsonb_build_object('ok',true,'duplicado',true,'id_linea',prior.id_linea);
 END IF;
 IF p.contrato_pdt<>'V2' OR p.estado<>'PENDIENTE' OR p.validacion_estado<>'VALIDADO'
  OR p.estado_repo NOT IN ('MECANIZADO','PROCESADO') OR p.fecha_cierre IS NOT NULL
 THEN RAISE EXCEPTION 'PDT_MANUAL_NO_APTO_PARA_ENTREGA'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=p_entrega FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_INEXISTENTE'; END IF;
 PERFORM 1 FROM public.sgp_mecanizado_programacion mp JOIN public.sgp_picking_entregas pe USING(id_programacion)
  WHERE pe.id_entrega=p_entrega FOR UPDATE OF mp;
 PERFORM 1 FROM public.sgp_picking_entregas pe JOIN public.sgp_mecanizado_programacion mp USING(id_programacion)
 JOIN public.sgp_producciones prod ON prod.key_produccion=p.key_produccion
 WHERE pe.id_entrega=p_entrega AND pe.produccion=prod.produccion
 AND upper(btrim(mp.sistema))=upper(btrim(prod.sistema)) AND upper(btrim(mp.acabado))=upper(btrim(d.acabado))
 AND (mp.reserva=p.reserva OR (mp.reserva=p.reserva_principal AND EXISTS(
  SELECT 1 FROM public.sgp_produccion_reservas_v rel WHERE rel.key_produccion=p.key_produccion
  AND rel.reserva=p.reserva AND rel.reserva_principal=mp.reserva)));
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_AJENA'; END IF;
 SELECT coalesce(sum(CASE WHEN tipo='AVANCE' THEN cantidad ELSE -cantidad END),0) INTO neto
 FROM public.sgp_aluminio_pendiente_movimientos WHERE id_detalle=p_detalle;
 IF p_cantidad+coalesce((SELECT sum(cantidad) FROM sgp_pdt_manual.entregas
  WHERE id_detalle=p_detalle AND estado<>'ANULADA'),0)>neto
 THEN RAISE EXCEPTION 'PDT_MANUAL_ENTREGA_SUPERA_PROCESADO'; END IF;
 INSERT INTO sgp_pdt_manual.entregas(id_detalle,id_entrega,cantidad,clave,registrado_por)
 VALUES(p_detalle,p_entrega,p_cantidad,p_clave,actor) RETURNING id_linea INTO nuevo;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(p.id_pendiente,actor,p.estado,p.estado,'ENTREGA_MANUAL_PDT',jsonb_build_object('linea',nuevo,'detalle',p_detalle,'entrega',p_entrega,'cantidad',p_cantidad));
 RETURN jsonb_build_object('ok',true,'id_linea',nuevo);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_manual_entrega_validar_v1(p_token text, p_linea uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE line sgp_pdt_manual.entregas%rowtype; parent uuid; actor text; parent_state text;
BEGIN
 actor:=public.sgp_pdt_validar_rol_real(p_token,ARRAY['ADMINISTRADOR','COORDINADOR','RECEPCION','SUPERVISOR DE PICKING']);
 SELECT d.id_pendiente INTO STRICT parent FROM sgp_pdt_manual.entregas l
 JOIN public.sgp_aluminio_pendiente_detalles d USING(id_detalle) WHERE l.id_linea=p_linea;
 SELECT estado INTO parent_state FROM public.sgp_aluminio_pendientes WHERE id_pendiente=parent AND estado='PENDIENTE' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_CERRADO'; END IF;
 SELECT * INTO STRICT line FROM sgp_pdt_manual.entregas WHERE id_linea=p_linea FOR UPDATE;
 IF line.estado='VALIDADA' THEN RETURN jsonb_build_object('ok',true,'duplicado',true); END IF;
 IF line.estado<>'REGISTRADA' THEN RAISE EXCEPTION 'PDT_MANUAL_LINEA_NO_APTA'; END IF;
 PERFORM 1 FROM public.sgp_picking_entregas WHERE id_entrega=line.id_entrega AND estado='VALIDADA' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PDT_MANUAL_PICKING_SIN_VALIDACION'; END IF;
 UPDATE sgp_pdt_manual.entregas SET estado='VALIDADA',validado_por=actor,validado_en=now() WHERE id_linea=p_linea;
 INSERT INTO public.sgp_aluminio_pendientes_historial(id_pendiente,usuario,estado_anterior,estado_nuevo,tipo_evento,datos_nuevos)
 VALUES(parent,actor,parent_state,parent_state,'VALIDACION_ENTREGA_MANUAL_PDT',jsonb_build_object('linea',p_linea));
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.sgp_pdt_proteger_entrega_origen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.sgp_pdt_entrega_lineas WHERE id_entrega=OLD.id_entrega AND estado<>'ANULADA') THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Entrega con evidencia PDT vigente'; END IF;
  IF ROW(NEW.produccion,NEW.id_programacion) IS DISTINCT FROM ROW(OLD.produccion,OLD.id_programacion) THEN
   RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar entrega';
  END IF;
  -- Registered quantities do not certify delivery: let the legacy audit produce
  -- VALIDADA or AUDITADA_DIFERENCIA. Once certified, annul explicitly first.
  IF NEW.estado IS DISTINCT FROM OLD.estado AND EXISTS(
   SELECT 1 FROM public.sgp_pdt_entrega_lineas WHERE id_entrega=OLD.id_entrega AND estado='VALIDADA') THEN
   RAISE EXCEPTION 'Conciliar evidencia PDT antes de modificar entrega';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sgp_picking_validar_recepcion(p_token text, p_id_entrega uuid, p_faltantes jsonb DEFAULT '[]'::jsonb, p_diferencias jsonb DEFAULT '[]'::jsonb, p_observacion text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text; e record; f jsonb; d jsonb; v_diff boolean:=false; v_key text; v_shared boolean:=false; v_principal text; v_pending_res text; v_finish text; v_nuevo uuid;
begin
 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','PICKING','SUPERVISOR DE PICKING','LIDER LINEA','LIDER']);
 select pe.*,mp.reserva into e from public.sgp_picking_entregas pe join public.sgp_mecanizado_programacion mp on mp.id_programacion=pe.id_programacion where pe.id_entrega=p_id_entrega for update;
 if e.id_entrega is null then raise exception 'Entrega no encontrada'; end if;
 if e.estado<>'PENDIENTE_VALIDACION' then raise exception 'La entrega ya fue auditada'; end if;
 select v.key_produccion,v.reserva_principal,bool_or(v.es_reserva_compartida)
 into v_key,v_principal,v_shared
 from public.sgp_produccion_reservas_v v
 where v.produccion=e.produccion and v.reserva_principal=e.reserva
 group by v.key_produccion,v.reserva_principal
 order by max(v.semana_produccion) desc limit 1;
 v_principal:=coalesce(v_principal,e.reserva);v_shared:=coalesce(v_shared,false);

 if public.sgp_mecanizado_es_parte(e.id_programacion) then
  select pt.key_produccion,mp.reserva,public.sgp_es_reserva_compartida(pt.key_produccion)
  into strict v_key,v_principal,v_shared from sgp_mecanizado_parcial.partes pt
  join public.sgp_mecanizado_programacion mp using(id_programacion) where pt.id_programacion=e.id_programacion;
 end if;
 for f in select value from jsonb_array_elements(coalesce(p_faltantes,'[]')) loop
  if public.sgp_mecanizado_es_parte(e.id_programacion) and (f->>'ventanas_afectadas')::integer>(select cantidad from sgp_mecanizado_parcial.partes where id_programacion=e.id_programacion) then raise exception 'VENTANAS_AFECTADAS_SUPERAN_PARTE'; end if;
  if public.sgp_mecanizado_es_parte(e.id_programacion) and not exists(
   select 1 from public.sgp_picking_faltantes pf where pf.id_faltante=(f->>'id_faltante')::uuid
   and pf.id_entrega=p_id_entrega and pf.id_pieza is not distinct from nullif(f->>'id_pieza','')
  ) then raise exception 'FALTANTE_AJENO_A_ENTREGA'; end if;
  if coalesce((f->>'ventanas_afectadas')::int,0)<1 then raise exception 'Indique las ventanas afectadas de cada faltante'; end if;
  update public.sgp_picking_faltantes set ventanas_afectadas=(f->>'ventanas_afectadas')::int,auditado=true,usuario_auditoria=u,fecha_auditoria=now()
   where id_faltante=(f->>'id_faltante')::uuid and id_entrega=p_id_entrega;
  update public.sgp_aluminio_pendientes set ventanas_afectadas=(f->>'ventanas_afectadas')::int,auditado=true
   where produccion=e.produccion and id_pieza is not distinct from nullif(f->>'id_pieza','') and estado='PENDIENTE'
     and (reserva=e.reserva or reserva=(select pf.reserva_pendiente from public.sgp_picking_faltantes pf where pf.id_faltante=(f->>'id_faltante')::uuid)) and (not public.sgp_mecanizado_es_parte(e.id_programacion) or exists(select 1 from sgp_mecanizado_parcial.contextos_pdt src where src.id_pendiente=public.sgp_aluminio_pendientes.id_pendiente and src.id_entrega=p_id_entrega));
 end loop;
 for d in select value from jsonb_array_elements(coalesce(p_diferencias,'[]')) loop
  if public.sgp_mecanizado_es_parte(e.id_programacion) and (nullif(d->>'id_pieza','') is null or (d->>'cantidad') is null or (d->>'cantidad')::numeric<=0 or (d->>'cantidad')::numeric<>trunc((d->>'cantidad')::numeric) or (d->>'cantidad')::numeric>(select cantidad from public.sgp_aluminio where id_pieza=d->>'id_pieza')) then raise exception 'CANTIDAD_MATERIAL_INVALIDA'; end if;
  if public.sgp_mecanizado_es_parte(e.id_programacion) and coalesce((d->>'ventanas_afectadas')::integer,1)>(select cantidad from sgp_mecanizado_parcial.partes where id_programacion=e.id_programacion) then raise exception 'VENTANAS_AFECTADAS_SUPERAN_PARTE'; end if;
  v_diff:=true;
  v_pending_res:=coalesce(nullif(trim(d->>'reserva'),''),e.reserva);
  if v_key is not null and not exists(select 1 from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_pending_res) then
    raise exception 'Seleccione una reserva válida para la diferencia de la orden con reserva compartida';
  end if;
  select v.acabado_reserva into v_finish from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_pending_res limit 1;
  v_finish:=coalesce(nullif(trim(d->>'acabado'),''),v_finish);
  insert into public.sgp_picking_auditoria_diferencias(id_entrega,id_pieza,perfil,marca,fabricacion,longitud,cantidad,ventanas_afectadas,observacion,usuario_auditoria,reserva_pendiente,acabado_pendiente)
  values(p_id_entrega,nullif(d->>'id_pieza',''),d->>'perfil',nullif(d->>'marca',''),nullif(d->>'fabricacion',''),nullif(d->>'longitud','')::numeric,
         greatest(coalesce((d->>'cantidad')::numeric,1),1),greatest(coalesce((d->>'ventanas_afectadas')::int,1),1),nullif(d->>'observacion',''),u,v_pending_res,v_finish);
  insert into public.sgp_aluminio_pendientes(
    reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,
    produccion,perfil,cantidad,longitud,origen,causa,observacion,estado,usuario_reporte,id_pieza,marca,fabricacion,estado_repo,ventanas_afectadas,auditado
  ) values(
    v_pending_res,v_principal,v_key,v_shared,v_finish,e.produccion,d->>'perfil',
    greatest(coalesce((d->>'cantidad')::numeric,1),1),nullif(d->>'longitud','')::numeric,
    'PICKING_AUDITORIA','DIFERENCIA_AUDITORIA',nullif(d->>'observacion',''),'PENDIENTE',u,
    nullif(d->>'id_pieza',''),nullif(d->>'marca',''),nullif(d->>'fabricacion',''),'PENDIENTE',
    greatest(coalesce((d->>'ventanas_afectadas')::int,1),1),true
  ) returning id_pendiente into v_nuevo;
  if public.sgp_mecanizado_es_parte(e.id_programacion) then insert into sgp_mecanizado_parcial.origenes_pdt values(v_nuevo,p_id_entrega); end if;
 end loop;
 update public.sgp_picking_entregas set estado=case when v_diff then 'AUDITADA_DIFERENCIA' else 'VALIDADA' end,usuario_validacion=u,fecha_validacion=now(),
